queries.areas:
SELECT ?area ?en ?pop ?when WHERE {
  VALUES ?area { $ITEMS }
  OPTIONAL { ?area rdfs:label ?en . FILTER(LANG(?en) = "en") }
  OPTIONAL { ?area p:P1082 ?statement . ?statement a wikibase:BestRank ; ps:P1082 ?pop . OPTIONAL { ?statement pq:P585 ?when } }
}
